"""Stage 4 file-writing primitives: new generated files carry a DO-NOT-EDIT header; edits to
existing files are confined to marker-wrapped blocks, with the target file's own line-ending
style (LF or CRLF) preserved exactly — a naive read/write round-trip silently normalizes CRLF
files to LF, turning a 2-line hook into a whole-file diff."""
from __future__ import annotations

from pathlib import Path
from typing import Literal

GENERATED_HEADER = "# Code generated by CodeSpectra AEH. DO NOT EDIT."


def _detect_newline(text: str) -> str:
    crlf = text.count("\r\n")
    lf_only = text.count("\n") - crlf
    return "\r\n" if crlf > 0 and crlf >= lf_only else "\n"


def _read_raw(path: Path) -> str:
    """`Path.read_text()` has no `newline` param and always applies universal-newline
    translation (silently turning \\r\\n into \\n) — read via `open()` to get the literal bytes."""
    with path.open(encoding="utf-8", newline="") as f:
        return f.read()


def write_generated_file(path: Path, content: str, *, newline: str = "\n") -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    body = GENERATED_HEADER + newline + content
    if newline != "\n":
        body = body.replace("\n", newline)
    path.write_text(body, encoding="utf-8", newline="")


def _marker_lines(marker_id: str, newline: str) -> tuple[str, str]:
    return f"# aeh:begin {marker_id}{newline}", f"# aeh:end {marker_id}{newline}"


def apply_marker_block(
    path: Path,
    marker_id: str,
    block: str,
    *,
    anchor: str | None = None,
    where: Literal["before", "after"] = "after",
) -> None:
    """Inserts `block` between `# aeh:begin <marker_id>` / `# aeh:end <marker_id>` markers.
    Re-running with the same marker_id replaces the block in place (idempotent). `anchor`
    (a literal substring matched against one line) positions the new block relative to that
    line; omitted, the block goes at the top of the file — the right default for import-order
    -sensitive hooks."""
    original = _read_raw(path)
    newline = _detect_newline(original)
    begin, end = _marker_lines(marker_id, newline)
    # `block` is caller-supplied Python source using plain "\n" — normalize every internal
    # line ending to the target file's own style before inserting, or a multi-line block
    # into a CRLF file mixes conventions (git then rewrites it on the next checkout/diff,
    # and a stray extra blank line appears wherever "\n" met the appended newline).
    normalized_block = block.replace("\r\n", "\n").replace("\n", newline)
    block_text = normalized_block if normalized_block.endswith(newline) else normalized_block + newline

    if begin in original and end in original:
        before, _, rest = original.partition(begin)
        _, _, after = rest.partition(end)
        new_content = f"{before}{begin}{block_text}{end}{after}"
    else:
        marked = f"{begin}{block_text}{end}"
        if anchor is None:
            new_content = marked + original
        else:
            lines = original.splitlines(keepends=True)
            idx = next((i for i, line in enumerate(lines) if anchor in line), None)
            if idx is None:
                raise ValueError(f"anchor {anchor!r} not found in {path}")
            insert_at = idx + 1 if where == "after" else idx
            lines[insert_at:insert_at] = [marked]
            new_content = "".join(lines)
    path.write_text(new_content, encoding="utf-8", newline="")


def remove_marker_block(path: Path, marker_id: str) -> bool:
    """Deletes everything between (and including) the marker pair. Returns False if the
    markers weren't found — idempotent no-op, uninstrument never errors on partial state."""
    original = _read_raw(path)
    newline = _detect_newline(original)
    begin, end = _marker_lines(marker_id, newline)
    if begin not in original or end not in original:
        return False
    before, _, rest = original.partition(begin)
    _, _, after = rest.partition(end)
    path.write_text(before + after, encoding="utf-8", newline="")
    return True
